const COOKIE = "urbexity_session";
const SESSION_DAYS = 30;
const MAX_JSON = 64 * 1024;
const IMAGE_LIMIT = 8 * 1024 * 1024;
const JSON_HEADERS = { "content-type": "application/json; charset=utf-8", "cache-control": "no-store" };

class HttpError extends Error {
  constructor(status, code, message) { super(message); this.status = status; this.code = code; }
}
const now = () => new Date().toISOString();
const id = () => crypto.randomUUID();
const bytesToHex = (bytes) => [...new Uint8Array(bytes)].map((n) => n.toString(16).padStart(2, "0")).join("");
const digest = async (value) => bytesToHex(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value)));
const randomToken = (n = 32) => { const bytes = crypto.getRandomValues(new Uint8Array(n)); return btoa(String.fromCharCode(...bytes)).replaceAll("+", "-").replaceAll("/", "_").replaceAll("=", ""); };
