function detectImage(b) {
  if(b[0]===0xff&&b[1]===0xd8&&b[2]===0xff)return{ext:"jpg",type:"image/jpeg"};
  if(b[0]===0x89&&b[1]===0x50&&b[2]===0x4e&&b[3]===0x47)return{ext:"png",type:"image/png"};
  if(String.fromCharCode(...b.slice(0,4))==="RIFF"&&String.fromCharCode(...b.slice(8,12))==="WEBP")return{ext:"webp",type:"image/webp"};
  if(String.fromCharCode(...b.slice(4,12)).includes("ftypavif"))return{ext:"avif",type:"image/avif"};return null;
}
async function verifyApiKey(request,env){const auth=request.headers.get("authorization")||"";if(!auth.startsWith("Bearer urbx_"))return null;const hash=await digest(auth.slice(7));const key=await env.DB.prepare("SELECT id,name,scopes_json,created_by FROM api_keys WHERE key_hash=?1 AND revoked_at IS NULL").bind(hash).first();if(!key)return null;await env.DB.prepare("UPDATE api_keys SET last_used_at=?1 WHERE id=?2").bind(now(),key.id).run();return key;}
async function serveWebhook(env, delivery) {
  const payload=JSON.parse(delivery.payload_json);let url=env.DISCORD_WEBHOOK_URL;
  let signingSecret=null;
  if(delivery.subscription_id){const sub=await env.DB.prepare("SELECT target_url,events_json,secret_hash FROM webhook_subscriptions WHERE id=?1 AND active=1").bind(delivery.subscription_id).first();if(!sub||!JSON.parse(sub.events_json).includes(delivery.event_type)){await env.DB.prepare("UPDATE webhook_deliveries SET status='failed',last_error='subscription unavailable' WHERE id=?1").bind(delivery.id).run();return;}url=sub.target_url;signingSecret=sub.secret_hash;}
  let body;
  if (delivery.event_type.startsWith("place.")) {
    body = { embeds: [{
      title: payload.title || "Location update",
      description: payload.description || "A community location update is available.",
      url: payload.placeUrl ? `${env.APP_ORIGIN}${payload.placeUrl}` : undefined,
      color: 0xe64046,
      fields: [
        ...(payload.category ? [{ name: "Category", value: payload.category, inline: true }] : []),
        ...(payload.username ? [{ name: "Explorer", value: `[${payload.username}](${env.APP_ORIGIN}${payload.profileUrl || ""})`, inline: true }] : []),
        ...(payload.createdAt ? [{ name: "Submitted", value: payload.createdAt, inline: true }] : [])
      ],
      footer: { text: "Urbexity · Explore responsibly" }
    }] };
  } else body={content:`Urbexity event: ${delivery.event_type}`,embeds:[{description:JSON.stringify(payload).slice(0,1800),color:0xe64046}]};
  const rawBody=JSON.stringify(body),headers={"content-type":"application/json"};
  if(signingSecret){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(signingSecret),{name:"HMAC",hash:"SHA-256"},false,["sign"]);headers["x-urbexity-signature"]=`sha256=${bytesToHex(await crypto.subtle.sign("HMAC",key,new TextEncoder().encode(rawBody)))}`;headers["x-urbexity-event"]=delivery.event_type;headers["x-urbexity-delivery"]=delivery.id;}
  const response=await fetch(url,{method:"POST",headers,body:rawBody});const attempts=delivery.attempts+1;
  if(response.ok){await env.DB.prepare("UPDATE webhook_deliveries SET status='delivered',attempts=?1,last_status_code=?2,delivered_at=?3,last_error=NULL WHERE id=?4").bind(attempts,response.status,now(),delivery.id).run();return;}
  const terminal=attempts>=8;const delay=Math.min(3600,30*2**Math.min(attempts,7));await env.DB.prepare("UPDATE webhook_deliveries SET status=?1,attempts=?2,last_status_code=?3,last_error=?4,next_attempt_at=?5 WHERE id=?6").bind(terminal?"failed":"pending",attempts,response.status,`http_${response.status}`,new Date(Date.now()+delay*1000).toISOString(),delivery.id).run();
}
async function retryWebhooks(env) {
  const rows=await env.DB.prepare("SELECT * FROM webhook_deliveries WHERE status='pending' AND next_attempt_at<=?1 ORDER BY next_attempt_at LIMIT 25").bind(now()).all();for(const row of rows.results||[])try{await serveWebhook(env,row);}catch(e){const attempts=row.attempts+1,terminal=attempts>=8;await env.DB.prepare("UPDATE webhook_deliveries SET status=?1,attempts=?2,last_error=?3,next_attempt_at=?4 WHERE id=?5").bind(terminal?"failed":"pending",attempts,String(e.message).slice(0,180),new Date(Date.now()+Math.min(3600,30*2**Math.min(attempts,7))*1000).toISOString(),row.id).run();}
}
const scopeFor = (path) => path.startsWith("/api/v1/admin/moderation")||path.startsWith("/api/v1/admin/reports")?"moderation:write":path.startsWith("/api/v1/admin/webhooks")?"webhooks:write":path.startsWith("/api/v1/users/")?"users:read":path.startsWith("/api/v1/places")?"places:read":path==="/api/v1/stats"?"stats:read":path==="/api/v1/leaderboards"?"leaderboards:read":null;
async function apiKeyRoute(request,env,path,user){const authorization=request.headers.get("authorization")||"";if(!authorization.startsWith("Bearer urbx_"))return null;const key=await verifyApiKey(request,env);if(!key)fail(401,"invalid_api_key","The supplied API key is invalid or revoked.");const scopes=JSON.parse(key.scopes_json),required=scopeFor(path);if(required&&!scopes.includes(required))fail(403,"insufficient_scope",`This key requires scope ${required}.`);await rateLimit(env,`api:${key.id}`,120,60);if(path.startsWith("/api/v1/admin/")){const integrationUser={id:key.created_by,is_admin:false,scopes};return publicApi(request,env,path,integrationUser);}if(required)return publicApi(request,env,path,null);return null;}
export default {
  async fetch(request,env,ctx){
    const url=new URL(request.url),path=url.pathname;
    try {
      if(path.startsWith("/media/")){const key=decodeURIComponent(path.slice(7));if(!/^[a-zA-Z0-9/_-]+\.(jpg|png|webp|avif)$/.test(key))fail(404,"media_not_found","Media was not found.");return await mediaResponse(request,env,key);}
      if(path.startsWith("/api/")){
        if(request.method==="OPTIONS")return new Response(null,{status:204,headers:{"access-control-allow-origin":env.APP_ORIGIN,"access-control-allow-methods":"GET,POST,PATCH,DELETE,OPTIONS","access-control-allow-headers":"content-type,authorization","access-control-allow-credentials":"true","access-control-max-age":"600"}});
        const user=await authenticate(request,env);const keyed=await apiKeyRoute(request,env,path,user);if(keyed)return keyed;
        const response=await publicApi(request,env,path,user);if(response)return response;
        if(path.startsWith("/api/v1/admin/")&&request.headers.has("authorization")){const response=await publicApi(request,env,path,user);if(response)return response;}
        fail(404,"route_not_found","No API route matches this request.");
      }
      return env.ASSETS.fetch(request);
    } catch(error) {
      if(error instanceof HttpError)return json({error:{code:error.code,message:error.message}},error.status);
      console.error("request_failed",{path,method:request.method,message:error?.message||"unknown"});return json({error:{code:"internal_error",message:"The request could not be completed."}},500);
    }
  },
  async scheduled(_controller,env,ctx){ctx.waitUntil(retryWebhooks(env));}
};
